      it("清除走 replace", () => {
        expect(clearKind).toBe("replace");
      });

      it("清除后节不含 tls 键", () => {
        // 与原文一致：`in` 优先级高于 `??`，故不额外兜底 section 为空的情形。
        expect(!("tlsCertFile" in clearSection) && !("tlsKeyFile" in clearSection)).toBeTruthy();
