/**
 * dsh-lan-proxy — 转发核心（src/server/proxy/impl/proxy.ts）结构化单测。
 *
 * 覆盖本批未覆盖热点：
 * - bridgeCompressedWs：WebSocket 压缩桥接（真实 WS 连接，全 localhost，无外网）
 * - createLanProxy 转发错误处理（不可达上游 → 502，proxy error 分支）
 * - createLanProxy HTTPS 降级（HTTPS 端口被占 → HTTP-only）
 * - createLanProxy 围栏与参数校验（非回环 targetHost / 非法 targetPort）
 * - 纯函数边界用例（hostnameAllowed / isLoopbackTarget / formatAuthority /
 *   rewriteHeaders / compressWsPath / isCompressible / resolveCompressionOptions）
 *
 * 本文件由脚本式断言迁为 vitest 结构化用例（#722 阶段 1）：原每条 assert 对应一个
 * it，判定口径与断言集合均未改动。真实端口相关块以 beforeAll 包住原有 setup/观测
 * 序列、afterAll 回收句柄——每个 it 只做断言，操作顺序与原脚本逐行一致；端口一律
 * 沿用原动态分配（listen(0) / 占位服务器取端口），未引入任何固定端口。
 */
import { beforeAll, describe, expect, it } from "vitest";
import { createServer, request as httpRequest } from "node:http";
import type { AddressInfo } from "node:net";
import type { IncomingHttpHeaders } from "node:http";
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createHash } from "node:crypto";
import { constants as zlibConstants } from "node:zlib";
import { WebSocket as WsClient, WebSocketServer } from "ws";

// 单元层导入面（ARCHITECTURE-METHOD §8）：同域白盒直连 impl，不经包 barrel——
// 经 barrel 会把内部符号钉在包导出面上，让「包 ABI 收窄」永远被测试消费方挡住。
import {
  hostnameAllowed,
  formatAuthority,
  rewriteHeaders,
  bridgeUpstreamHeaders,
  createLanProxy,
  compressWsPath,
  isCompressible,
  resolveCompressionOptions,
  deflateAllowedByPolicy,
  hasDshAuthCookie,
  isTokenMintCandidate,
  withLaunchToken,
} from "../../src/server/proxy/impl/proxy.ts";
import { isLoopbackTarget } from "../../src/server/shared/net.ts";
import { DEFAULT_OPTIONS } from "../../src/server/shared/defaults.ts";
import { DEFAULT_DEFLATE_POLICY } from "../../src/server/shared/deflate.ts";
import { ensureSelfSignedTls } from "../../src/server/tls/impl/index.ts";
import { DEFAULT_WSS_COMPRESS_PATHS } from "../../src/server/config/impl/model.ts";

const sleep = (ms: number): Promise<void> => new Promise<void>((r) => setTimeout(r, ms));

/** 轮询等待条件成立（防 flake 纪律：替代固定 sleep 猜时序）；超时返回 false。 */
async function waitFor(predicate: () => boolean, deadlineMs = 5000, stepMs = 20) {
  const start = Date.now();
  while (!predicate()) {
    if (Date.now() - start > deadlineMs) return false;
    await sleep(stepMs);
  }
  return true;
}

/** RFC6455 握手应答行（Sec-WebSocket-Accept 计算；供 raw 假对端完成升级）。 */
const wsHandshakeResponse = (key: string) =>
  "HTTP/1.1 101 Switching Protocols\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n" +
  `Sec-WebSocket-Accept: ${createHash("sha1")
    .update(key + "258EAFA5-E914-47DA-95CA-C5AB0DC85B11")
    .digest("base64")}\r\n\r\n`;

/** 起一个 WS 回显上游（wsBridge 三态用例共用）。 */
async function mkUpstream() {
  const upServer = createServer();
  const wss = new WebSocketServer({ noServer: true });
  upServer.on("upgrade", (req, socket, head) => {
    wss.handleUpgrade(req, socket, head, (ws) => {
      ws.on("message", (data, isBinary) => ws.send(data, { binary: isBinary }));
    });
  });
  await new Promise<void>((r) => upServer.listen(0, "127.0.0.1", () => r()));
  const upPort = (upServer.address() as AddressInfo).port;
  return { upPort, upServer, wss };
}

/** 经代理建一条 WS 连接、等 open、重试发送帧至回显（上游段 open 竞态：桥接的
 *  浏览器段 message 监听在 upstreamWs open 后才挂载，过早帧会被丢——重试规避），
 *  关闭连接返回收到的帧。 */
async function openAndEcho(port: number, path: string): Promise<string[]> {
  const ws = new WsClient(`ws://127.0.0.1:${port}${path}`);
  const received: string[] = [];
  ws.on("message", (data) => received.push(data.toString()));
  await new Promise((r, j) => {
    ws.on("open", r);
    ws.on("error", j);
  });
  for (let i = 0; i < 6; i++) {
    ws.send(`ping-${path}-${i}`);
    if (await waitFor(() => received.length > 0, 800)) break;
  }
  ws.close();
  await sleep(100);
  return received;
}

// ===== 纯函数边界用例 =====

describe("纯函数边界用例", () => {
  describe("hostnameAllowed", () => {
    it("bare IPv4", () => expect(hostnameAllowed("127.0.0.1")).toBe(true));
    it("bracketed IPv6", () => expect(hostnameAllowed("[::1]")).toBe(true));
    it("empty string", () => expect(hostnameAllowed("")).toBe(false));
    it("非字符串（undefined）→ 拒绝", () => expect(hostnameAllowed(undefined)).toBe(false));
    it("any IPv4", () => expect(hostnameAllowed("0.0.0.0")).toBe(true));
    it("LAN IPv4", () => expect(hostnameAllowed("192.168.1.1")).toBe(true));
    it("端口越界 → URL 解析失败 → 拒绝", () =>
      expect(hostnameAllowed("127.0.0.1:99999")).toBe(false));
    it("localhost 字面量放行", () => expect(hostnameAllowed("localhost")).toBe(true));
    it("localhost 带端口放行", () => expect(hostnameAllowed("localhost:3080")).toBe(true));
    it("bracketed IPv6 带端口放行", () => expect(hostnameAllowed("[::1]:443")).toBe(true));
    it("DNS 域名拒绝（重绑定防护核心语义）", () =>
      expect(hostnameAllowed("example.com")).toBe(false));
    it("多级 DNS 域名拒绝", () => expect(hostnameAllowed("sub.example.org")).toBe(false));
    it("裸 IPv6 冒号 authority → URL 解析失败 → 拒绝", () =>
      expect(hostnameAllowed("::1")).toBe(false));
    // 以下两条原住 test/e2e（从产物导入），并入源码层白盒
    it("带端口的 IPv6 authority 放行", () => expect(hostnameAllowed("[fe80::1]:3081")).toBe(true));
    it("带 scheme 的 authority 拒绝（authority 不是 URL）", () =>
      expect(hostnameAllowed("http://evil.com:3081")).toBe(false));
  });

  describe("isLoopbackTarget", () => {
    it("loopback IPv4", () => expect(isLoopbackTarget("127.0.0.1")).toBe(true));
    it("loopback IPv6", () => expect(isLoopbackTarget("::1")).toBe(true));
    it("IPv4-mapped IPv6 loopback", () => expect(isLoopbackTarget("::ffff:127.0.0.1")).toBe(true));
    it("localhost", () => expect(isLoopbackTarget("localhost")).toBe(true));
    it("bracketed IPv6 loopback", () => expect(isLoopbackTarget("[::1]")).toBe(true));
    it("bracketed IPv4 loopback", () => expect(isLoopbackTarget("[127.0.0.1]")).toBe(true));
    it("bracketed mapped loopback", () =>
      expect(isLoopbackTarget("[::ffff:127.0.0.1]")).toBe(true));
    it("非回环拒绝", () => expect(isLoopbackTarget("192.168.1.1")).toBe(false));
    it("DNS 名拒绝", () => expect(isLoopbackTarget("evil.com")).toBe(false));
    it("空串拒绝", () => expect(isLoopbackTarget("")).toBe(false));
    it("非 .1 回环段仍按字面匹配语义拒绝", () => expect(isLoopbackTarget("127.0.0.2")).toBe(false));
    it('单侧括号不剥离（"[127.0.0.1x" 仍拒绝：&& 缺一即不 slice）', () =>
      expect(isLoopbackTarget("[127.0.0.1x")).toBe(false));
  });

  describe("formatAuthority", () => {
    it('formatAuthority("0.0.0.0", 3081) → "0.0.0.0:3081"', () => {
      expect(formatAuthority("0.0.0.0", 3081)).toBe("0.0.0.0:3081");
    });

    it('formatAuthority("::1", 3080) → "[::1]:3080"', () => {
      expect(formatAuthority("::1", 3080)).toBe("[::1]:3080");
    });

    it('formatAuthority("::ffff:10.0.0.1", 9090) → "[::ffff:10.0.0.1]:9090"', () => {
      expect(formatAuthority("::ffff:10.0.0.1", 9090)).toBe("[::ffff:10.0.0.1]:9090");
    });
  });

  describe("rewriteHeaders", () => {
    it("多键重写", () => {
      expect(
        rewriteHeaders({ host: "x:1", origin: "http://x:1", "x-custom": "v" }, "127.0.0.1:3080"),
      ).toEqual({
        host: "127.0.0.1:3080",
        origin: "http://127.0.0.1:3080",
        "x-custom": "v",
      });
    });

    it("Origin https→http", () => {
      expect(rewriteHeaders({ host: "x:1", origin: "https://x:1" }, "127.0.0.1:3080")).toEqual({
        host: "127.0.0.1:3080",
        origin: "http://127.0.0.1:3080",
      });
    });

    it("空头只加 host", () => {
      expect(rewriteHeaders({}, "127.0.0.1:3080")).toEqual({ host: "127.0.0.1:3080" });
    });

    it("多值头（string[]）同样整体覆盖为单值 authority", () => {
      expect(
        rewriteHeaders(
          { host: ["a", "b"], origin: ["http://a"] } as unknown as IncomingHttpHeaders,
          "127.0.0.1:9",
        ),
      ).toEqual({
        host: "127.0.0.1:9",
        origin: "http://127.0.0.1:9",
      });
    });

    // 原对象不被修改（浅拷贝语义）
    it("入参 headers 不被就地修改", () => {
      const src = { host: "old:1" };
      rewriteHeaders(src, "127.0.0.1:2");
      expect(src.host).toBe("old:1");
    });

    // 以下两条原住 test/e2e（从产物导入），并入源码层白盒
    it("非 Host/Origin 的头原样保留", () => {
      const out = rewriteHeaders(
        { host: "192.168.1.50:3081", "user-agent": "x" },
        "127.0.0.1:3080",
      );
      expect(out["user-agent"]).toBe("x");
    });

    it("缺席的 Origin 不会凭空补出", () => {
      const out = rewriteHeaders({ host: "192.168.1.50:3081" }, "127.0.0.1:3080");
      expect(out.origin).toBe(undefined);
    });
  });

  describe("bridgeUpstreamHeaders（issue #379：压缩桥接上游连接入站头透传）", () => {
    it("透传认证/自定义头，重写 Host/Origin，剥离 hop-by-hop 与 WS 握手专有头", () => {
      expect(
        bridgeUpstreamHeaders(
          {
            host: "192.168.1.50:3081",
            origin: "http://192.168.1.50:3081",
            cookie: "dsh-auth-x=v1.aaa",
            "x-custom": "v",
            connection: "Upgrade",
            upgrade: "websocket",
            "sec-websocket-key": "AAA=",
            "sec-websocket-version": "13",
            "sec-websocket-extensions": "permessage-deflate",
          },
          "127.0.0.1:3080",
        ),
      ).toEqual({
        cookie: "dsh-auth-x=v1.aaa",
        "x-custom": "v",
        host: "127.0.0.1:3080",
        origin: "http://127.0.0.1:3080",
      });
    });

    it("空头仍产出回环 Host/Origin（无条件带 origin 与桥接既有行为一致）", () => {
      expect(bridgeUpstreamHeaders({}, "127.0.0.1:3080")).toEqual({
        host: "127.0.0.1:3080",
        origin: "http://127.0.0.1:3080",
      });
    });

    it("多值头（string[]）合并为逗号串", () => {
      expect(
        bridgeUpstreamHeaders(
          { cookie: ["a=1", "b=2"] } as unknown as IncomingHttpHeaders,
          "127.0.0.1:1",
        ),
      ).toEqual({
        cookie: "a=1, b=2",
        host: "127.0.0.1:1",
        origin: "http://127.0.0.1:1",
      });
    });

    it("入参 headers 不被就地修改", () => {
      const src = { cookie: "c=1" };
      bridgeUpstreamHeaders(src, "127.0.0.1:2");
      expect(src).toEqual({ cookie: "c=1" });
    });

    // 分支补充：大写键名归一化小写、undefined 值跳过、hop-by-hop 全集与 WS 握手头剥离
    it("大写键名归一化、undefined 跳过、Proxy-Authorization/te/trailer/transfer-encoding/sec-websocket-protocol 剥离", () => {
      expect(
        bridgeUpstreamHeaders(
          {
            Cookie: "c=1",
            "X-Undefined": undefined,
            "Proxy-Authorization": "Basic x",
            te: "trailers",
            trailer: "x-foo",
            "transfer-encoding": "chunked",
            "sec-websocket-protocol": "chat",
          },
          "127.0.0.1:3080",
        ),
      ).toEqual({
        cookie: "c=1",
        host: "127.0.0.1:3080",
        origin: "http://127.0.0.1:3080",
      });
    });

    // L2（#395）：sec-websocket-accept 是响应头、请求侧不可达，不在剥离集——入站若
    // 恰好携带该头则原样透传（deny 集仅针对请求侧可达头，防回归误加回剥离集）。
    it("sec-websocket-accept 不再被剥离（响应头请求侧不可达）", () => {
      expect(
        bridgeUpstreamHeaders({ "sec-websocket-accept": "ABC=", cookie: "c=1" }, "127.0.0.1:3080"),
      ).toEqual({
        "sec-websocket-accept": "ABC=",
        cookie: "c=1",
        host: "127.0.0.1:3080",
        origin: "http://127.0.0.1:3080",
      });
    });
  });

  describe("compressWsPath", () => {
    it("带查询串命中", () => expect(compressWsPath(["/a", "/b"], "/a?query=1")).toBe(true));
    it("未命中", () => expect(compressWsPath(["/a", "/b"], "/c")).toBe(false));
    it("空列表", () => expect(compressWsPath([], "/a")).toBe(false));
    it("undefined 列表", () => expect(compressWsPath(undefined, "/a")).toBe(false));
    it("空 url", () => expect(compressWsPath(["/a"], "")).toBe(false));
    // 以下两条原住 test/e2e，并入源码层白盒（前者同时锁默认白名单的实际取值）
    it("默认白名单命中 remote.mux（忽略查询串）", () =>
      expect(compressWsPath(DEFAULT_WSS_COMPRESS_PATHS, "/api/remote.mux?x=1")).toBe(true));
    it("非默认白名单（自定义 path）命中", () =>
      expect(compressWsPath(["/custom/ws"], "/custom/ws")).toBe(true));
    // 原住 test/e2e，并入源码层白盒：默认白名单常量的实际取值本身也是契约
    it("默认白名单常量的实际取值", () =>
      expect(DEFAULT_WSS_COMPRESS_PATHS).toEqual(["/api/remote.mux"]));
  });

  describe("isCompressible", () => {
    it("problem+json", () => expect(isCompressible("application/problem+json")).toBe(true));
    it("带 charset 的 text", () => expect(isCompressible("text/plain; charset=utf-8")).toBe(true));
    it("SSE 豁免", () => expect(isCompressible("text/event-stream")).toBe(false));
    it("图片不压", () => expect(isCompressible("image/png")).toBe(false));
    it("非字符串不压", () => expect(isCompressible(123)).toBe(false));
    // 以下原住 test/e2e（从产物导入），并入源码层白盒
    it("application/json", () => expect(isCompressible("application/json")).toBe(true));
    it("application/json; charset=utf-8", () =>
      expect(isCompressible("application/json; charset=utf-8")).toBe(true));
    it("结构化 +json 后缀", () => expect(isCompressible("application/vnd.test+json")).toBe(true));
    it("text/html", () => expect(isCompressible("text/html")).toBe(true));
    it("zip 豁免", () => expect(isCompressible("application/zip")).toBe(false));
    it("undefined 不压", () => expect(isCompressible(undefined)).toBe(false));
  });

  describe("resolveCompressionOptions", () => {
    const Q = zlibConstants.BROTLI_PARAM_QUALITY;
    it("0 → 默认", () => expect(resolveCompressionOptions(0)).toEqual({}));
    it("undefined → 默认", () => expect(resolveCompressionOptions(undefined)).toEqual({}));
    it("字符串 → 默认", () => expect(resolveCompressionOptions("high")).toEqual({}));
    it("null → 默认", () => expect(resolveCompressionOptions(null)).toEqual({}));
    // 档位矩阵原住 test/e2e（从产物导入）——源码层此前只覆盖「非法 → 默认」，
    // 档位到 gzip level / Brotli 质量的映射在单元层是空的，属层归属倒置的反向缺口。
    it.each([NaN, -3, 4.5, 99].map((v) => ({ v })))("非法档位 %s → 默认", ({ v }) => {
      expect(resolveCompressionOptions(v)).toEqual({});
    });

    it("1 低档 → gzip level=1", () => expect(resolveCompressionOptions(1).level).toBe(1));

    it("1 低档 → brotli 质量 2", () =>
      expect(resolveCompressionOptions(1).brotli!.params[Q]).toBe(2));

    it("2 中档 → gzip level=5", () => expect(resolveCompressionOptions(2).level).toBe(5));

    it("2 中档 → brotli 质量 5", () =>
      expect(resolveCompressionOptions(2).brotli!.params[Q]).toBe(5));

    it("3 高档 → gzip level=9", () => expect(resolveCompressionOptions(3).level).toBe(9));

    it("3 高档 → brotli 质量 9", () =>
      expect(resolveCompressionOptions(3).brotli!.params[Q]).toBe(9));
  });

  describe("launch token 判定（issue #380：hasDshAuthCookie / isTokenMintCandidate / withLaunchToken）", () => {
    describe("hasDshAuthCookie", () => {
      it("单个 dsh-auth- 前缀 cookie → true", () =>
        expect(hasDshAuthCookie("dsh-auth-x=1")).toBe(true));
      it("值里含 dsh-auth- 子串的无关 cookie → false（禁整头子串匹配）", () =>
        expect(hasDshAuthCookie("other=dsh-auth-x")).toBe(false));
      it("多段 cookie 中第二段命中 → true", () =>
        expect(hasDshAuthCookie("a=1; dsh-auth-y=2")).toBe(true));
      it("数组头按段处理：命中段 → true", () =>
        expect(hasDshAuthCookie(["a=1", "dsh-auth-z=3"])).toBe(true));
      it("数组头按段处理：值含子串仍 → false", () =>
        expect(hasDshAuthCookie(["a=1", "other=dsh-auth-z"])).toBe(false));
      it("undefined → false", () => expect(hasDshAuthCookie(undefined)).toBe(false));
      it("空串 → false", () => expect(hasDshAuthCookie("")).toBe(false));
      it("无 = 的段被跳过（不当作 cookie 名）", () =>
        expect(hasDshAuthCookie("dsh-auth-x; b=2")).toBe(false));
    });

    describe("isTokenMintCandidate", () => {
      it('("GET", "/") → true', () => expect(isTokenMintCandidate("GET", "/")).toBe(true));
      it('("GET", "/?token=x") → false（已带 token）', () =>
        expect(isTokenMintCandidate("GET", "/?token=x")).toBe(false));
      it('("POST", "/") → false', () => expect(isTokenMintCandidate("POST", "/")).toBe(false));
      it('("GET", "/other") → false', () =>
        expect(isTokenMintCandidate("GET", "/other")).toBe(false));
      it("url undefined → false", () => expect(isTokenMintCandidate("GET", undefined)).toBe(false));
      it('绝对 URL "http://x/" → true（按 pathname 判定而非前缀匹配）', () =>
        expect(isTokenMintCandidate("GET", "http://x/")).toBe(true));
    });

    describe("withLaunchToken", () => {
      it('("/", "t") → "/?token=t"', () => expect(withLaunchToken("/", "t")).toBe("/?token=t"));
      it("已有 token → 覆盖为新值（不追加）", () =>
        expect(withLaunchToken("/?token=old", "t")).toBe("/?token=t"));
      it('("/a?b=1", "t") → "/a?b=1&token=t"', () =>
        expect(withLaunchToken("/a?b=1", "t")).toBe("/a?b=1&token=t"));
      it("url undefined → undefined", () =>
        expect(withLaunchToken(undefined, "t")).toBe(undefined));
    });

    describe("deflateAllowedByPolicy", () => {
      it("策略 undefined → 放行", () =>
        expect(deflateAllowedByPolicy(undefined, "any-ua")).toBe(true));
      it("browser=false → 拒绝", () =>
        expect(deflateAllowedByPolicy({ browser: false }, "any-ua")).toBe(false));
      it("默认策略：iPhone 命中 uaDeny → 拒绝", () =>
        expect(
          deflateAllowedByPolicy(
            DEFAULT_DEFLATE_POLICY,
            "Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X)",
          ),
        ).toBe(false));
      it("默认策略：Chrome 不含 deny 片段 → 放行", () =>
        expect(
          deflateAllowedByPolicy(
            DEFAULT_DEFLATE_POLICY,
            "Mozilla/5.0 (X11; Linux x86_64) Chrome/120.0 Safari/537.36",
          ),
        ).toBe(true));
      it("自定义 uaDeny 命中 → 拒绝", () =>
        expect(deflateAllowedByPolicy({ uaDeny: ["Foo"] }, "Mozilla Foo/1")).toBe(false));
      it("UA 缺失且 uaDeny 非空 → 放行", () =>
        expect(deflateAllowedByPolicy({ uaDeny: ["Foo"] }, undefined)).toBe(true));
    });
  });

  describe("DEFAULT_OPTIONS 常量", () => {
