    it("DEFAULT_OPTIONS.port === 3081", () => expect(DEFAULT_OPTIONS.port).toBe(3081));
    it('DEFAULT_OPTIONS.targetHost === "127.0.0.1"', () =>
      expect(DEFAULT_OPTIONS.targetHost).toBe("127.0.0.1"));
