// ===== wsBridgeEnabled 三态路径选择（issue #552 解耦） =====
// 判别依据 connStats：桥接任一端 close → wsBridgeClosed+1；透传 socket 销毁 →
// wsPassthroughDestroyed+1。三种配置各建一条 WS 连接后关闭，断言走了预期路径：
//   a) wsBridge=false + 命中压缩白名单 → 透传（wsPassthroughDestroyed 增长）；
//   b) wsBridge=true + 未命中白名单 → 仍桥接（wsBridgeClosed 增长）；
//   c) wsBridge 缺省（旧行为兼容）→ 命中走桥接、未命中走透传。
describe("wsBridgeEnabled 三态路径选择（issue #552 解耦）", () => {
  // a) wsBridge=false：命中白名单路径也走透传
  describe("a) wsBridge=false", () => {
    let got: string[] = [];
    let cs: { wsPassthroughDestroyed: number; wsBridgeClosed: number } = {
      wsPassthroughDestroyed: 0,
      wsBridgeClosed: 0,
    };

    beforeAll(async () => {
      const u = await mkUpstream();
      const proxy = createLanProxy({
        host: "127.0.0.1",
        port: 0,
        targetHost: "127.0.0.1",
        targetPort: u.upPort,
        wsBridge: { enabled: false },
        wsCompress: { enabled: true, paths: ["/api/remote.mux"], probeIntervalMs: 0 },
      });
      const { httpPort } = await proxy.listen();
      got = await openAndEcho(httpPort, "/api/remote.mux");
      // 透传 socket 的销毁由 proxy 侧异步感知，openAndEcho 内的固定 sleep(100) 在高负载下
      // 不足（Stryker 沙箱与多文件并发跑均实测偶发）。改为等到计数真正增长再取快照；
      // 若 socket 始终没销毁，waitFor 超时后快照仍为 0、下面断言照旧判红——是去抖，不是放宽。
      await waitFor(() => proxy.connStats().wsPassthroughDestroyed >= 1, 5000);
      cs = proxy.connStats();
      await proxy.close();
      u.wss.close();
      u.upServer.close();
    }, 30000);

    it("wsBridge=false 命中白名单仍可转发（透传）", () => {
      expect(got.some((s) => s.startsWith("ping-/api/remote.mux"))).toBeTruthy();
    });

    it("wsBridge=false → 透传计数增长", () => {
      expect(cs.wsPassthroughDestroyed >= 1).toBeTruthy();
    });

    it("wsBridge=false → 不产生桥接连接", () => {
      expect(cs.wsBridgeClosed).toBe(0);
    });
  });

  // b) wsBridge=true：未命中白名单路径也走桥接（保活基座不依赖压缩白名单）
  describe("b) wsBridge=true", () => {
    let got: string[] = [];
    let cs: { wsPassthroughDestroyed: number; wsBridgeClosed: number } = {
      wsPassthroughDestroyed: 0,
      wsBridgeClosed: 0,
    };

    beforeAll(async () => {
      const u = await mkUpstream();
      const proxy = createLanProxy({
        host: "127.0.0.1",
        port: 0,
        targetHost: "127.0.0.1",
        targetPort: u.upPort,
        wsBridge: { enabled: true },
        wsCompress: { enabled: true, paths: ["/api/remote.mux"], probeIntervalMs: 0 },
      });
      const { httpPort } = await proxy.listen();
      got = await openAndEcho(httpPort, "/api/other");
      await waitFor(() => proxy.connStats().wsBridgeClosed >= 1, 5000);
      cs = proxy.connStats();
      await proxy.close();
      u.wss.close();
      u.upServer.close();
    }, 30000);

    it("wsBridge=true 未命中白名单仍可转发（桥接明文）", () => {
      expect(got.some((s) => s.startsWith("ping-/api/other"))).toBeTruthy();
    });

    it("wsBridge=true → 桥接计数增长", () => {
      expect(cs.wsBridgeClosed >= 1).toBeTruthy();
    });

    it("wsBridge=true → 不产生透传连接", () => {
      expect(cs.wsPassthroughDestroyed).toBe(0);
    });
  });

  // c) wsBridge 缺省（旧行为兼容）：命中白名单走桥接、未命中走透传
  describe("c) wsBridge 缺省（旧行为兼容）", () => {
    let cs: { wsPassthroughDestroyed: number; wsBridgeClosed: number } = {
      wsPassthroughDestroyed: 0,
      wsBridgeClosed: 0,
    };

    beforeAll(async () => {
      const u = await mkUpstream();
      const proxy = createLanProxy({
        host: "127.0.0.1",
        port: 0,
        targetHost: "127.0.0.1",
        targetPort: u.upPort,
        wsCompress: { enabled: true, paths: ["/api/remote.mux"], probeIntervalMs: 0 },
      });
      const { httpPort } = await proxy.listen();
      await openAndEcho(httpPort, "/api/remote.mux"); // 命中 → 桥接
      await openAndEcho(httpPort, "/api/other"); // 未命中 → 透传
      await waitFor(
        () =>
          proxy.connStats().wsBridgeClosed >= 1 && proxy.connStats().wsPassthroughDestroyed >= 1,
        5000,
      );
      cs = proxy.connStats();
      await proxy.close();
      u.wss.close();
      u.upServer.close();
    }, 30000);

    it("缺省 wsBridge：命中白名单走桥接", () => {
      expect(cs.wsBridgeClosed >= 1).toBeTruthy();
    });

    it("缺省 wsBridge：未命中白名单走透传", () => {
      expect(cs.wsPassthroughDestroyed >= 1).toBeTruthy();
    });
  });
});

// ===== 转发围栏与压缩协商的端到端行为（proxy 段补强） =====
// 以下用例经真实 createLanProxy 收口此前只在纯函数层断言的行为：
// 非 IP Host 不得进转发、PNA 预检放行、升级围栏、本地响应的压缩计数豁免、
// 桥接压缩协商（桌面协商 / iOS 明文）、慢响应断连传播、失效 cookie 自愈。
/** 经代理发 HTTP 请求并收完整响应（Host 头显式可控）。 */
async function proxyHttp(
  httpPort: number,
  options: { method?: string; path?: string; host?: string; headers?: Record<string, string> },
): Promise<{
  status: number;
  headers: Record<string, string | string[] | undefined>;
  body: string;
}> {
  return new Promise((resolve) => {
    const req = httpRequest(
      {
        hostname: "127.0.0.1",
        port: httpPort,
        path: options.path ?? "/",
        method: options.method ?? "GET",
        headers: { host: `127.0.0.1:${httpPort}`, ...(options.headers ?? {}) },
      },
      (res2) => {
        let body = "";
        res2.on("data", (c) => (body += c));
        res2.on("end", () =>
          resolve({
            status: res2.statusCode ?? 0,
            headers: res2.headers as Record<string, string | string[] | undefined>,
            body,
          }),
        );
      },
    );
    if (options.host !== undefined) req.setHeader("host", options.host);
    req.on("error", (e) => resolve({ status: 0, headers: {}, body: e.message }));
    req.end();
  });
}

